import random


def decrypt(ciphertext, seed):

    rng = random.Random(seed)
    plaintext = bytearray()

    for byte in ciphertext:
        key = rng.getrandbits(8)
        plaintext.append(byte ^ key)

    return bytes(plaintext)


print("===== MT19937 SEED RECOVERY =====")

# Enter ciphertext generated by Program 1
cipher_hex = input("\nEnter ciphertext (hex): ").strip()

ciphertext = bytes.fromhex(cipher_hex)

known_text = b"A" * 14

found = False
recovered_seed = None
recovered_plaintext = None

print("\nSearching all 65536 possible seeds...")

# Try every 16-bit seed
for seed in range(65536):

    plaintext = decrypt(ciphertext, seed)

    # Check whether known plaintext exists
    if known_text in plaintext:

        recovered_seed = seed
        recovered_plaintext = plaintext
        found = True

        break


# Display result
if found:

    print("\nSeed Recovered Successfully!")

    print("Recovered Seed:", recovered_seed)

    print("Recovered Plaintext:",
          recovered_plaintext.decode("ascii"))

    # Verify complete ciphertext decryption
    verification = decrypt(ciphertext, recovered_seed)

    print("\n===== VERIFICATION =====")

    print("Decryption Correct:",
          verification == recovered_plaintext)

    print("Contains 14 consecutive A's:",
          known_text in verification)

else:

    print("\nNo matching seed found.")